const dropsRows = $('Get rows DROPS').all();

const hoje = new Date();
const hojeStr = hoje.toLocaleDateString('pt-BR');

const dropsHoje = dropsRows.filter(item => {
  const data = item.json['DATA PREVISTA'];
  const status = (item.json['STATUS'] || '').trim().toLowerCase();
  return data === hojeStr && status !== 'concluido' && status !== 'concluído';
});

const grupos = {};
dropsHoje.forEach(item => {
  const dia = item.json['DIA DROP'];
  const tanque = item.json['TANQUE'];
  const tipoTanque = (item.json['TIPO TANQUE'] || '').trim().toLowerCase();
  const navio = item.json['NAVIO'];

  if (!grupos[dia]) grupos[dia] = { terra: [], navios: {} };

  if (tipoTanque === 'navio' && navio) {
    (grupos[dia].navios[navio] ??= []).push(tanque);
  } else {
    grupos[dia].terra.push(tanque);
  }
});

const ordem = ['D5', 'D10', 'D15'];
const linhas = ordem
  .filter(dia => grupos[dia])
  .map(dia => {
    const g = grupos[dia];
    const partes = [...g.terra];
    Object.entries(g.navios).forEach(([nome, tanques]) => {
      partes.push(`${tanques.join(',')}  NAVIO ${nome}`);
    });
    const diasNum = parseInt(dia.replace('D', ''), 10);
    const dataColeta = new Date(hoje);
    dataColeta.setDate(dataColeta.getDate() - diasNum);
    return `${dia} -  Tanques ${partes.join(', ')} - coletados ${dataColeta.toLocaleDateString('pt-BR')}`;
  });

const texto = linhas.length
  ? linhas.join('\n')
  : `Nenhum drop previsto para hoje (${hojeStr}).`;

return [{ json: { textoResposta: texto } }];

